// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** The 20 Critical Patient Safety Areas of the PHC's HCE web portal and every document they require. */
export interface CpsaOverviewOut {
  date_from: string;
  date_to: string;
  /** The user's preference (PUT /settings/me pdf_download): Separate = a download button per document (pdf_url); Combined = one button for combined_pdf_url. Never a ZIP */
  download_mode: "Separate" | "Combined";
  /** Every filled document as one PDF with a contents page, area by area */
  combined_pdf_url: string;
  /** The declaration (Annexure A) on the PHC's form: the confirmed answers, the records' answers marked * until a person confirms them */
  declaration_pdf_url: string;
  /** The PHC's 'Guidelines for CPSAs' (Word), as published */
  guidelines_url: string;
  counts: CpsaCountsOut;
  areas: CpsaAreaOut[];
}

export interface CpsaCountsOut {
  documents: number;
  available: number;
  trained: number;
  training_applies: number;
  implemented: number;
  implementation_applies: number;
  uploaded: number;
  uploads_recorded: number;
  /** The rows of the declaration (Annexure A) */
  declaration_rows: number;
  /** Rows whose every answerable column a person has confirmed */
  declaration_rows_confirmed: number;
}

export interface CpsaAreaOut {
  area: number;
  title: string;
  documents: CpsaDocumentOut[];
}

/** One document the PHC asks for, with how Haspataal provides it. */
export interface CpsaDocumentOut {
  key: string;
  area: number;
  /** The PHC's numbering, e.g. 2.1 */
  number: string;
  title: string;
  kind: "Format" | "Policy" | "Register" | "Notification" | "Upload" | "Guideline";
  about: string;
  department: string;
  /** The declaration rows (the PHC's wording) this document answers */
  declaration: string[];
  /** The training requirement whose sessions print as the attendance sheet */
  training_code: string | null;
  /** Names patients: every download is logged like a read of a record */
  phi: boolean;
  /** The PHC's own file (Word, Excel or PDF), downloadable as it is; null when the PHC gives none */
  template: string | null;
  /** GET: the PHC's file as published on the web portal */
  template_url: string | null;
  /** GET: the document filled from the records as a PDF (null: nothing to fill) */
  pdf_url: string | null;
  /** GET: filled into the PHC's Excel format (the four lists of CPSA 1 the PHC accepts only in Excel) */
  xlsx_url: string | null;
  status: CpsaStatusOut;
  /** The declaration rows this document answers, with each column's final answer and who confirmed it */
  rows: DeclarationRowOut[];
}

/** The records' four answers for one document, each with the reason (checks.py, evidence.py): "Yes" only from evidence, never because Haspataal can print the document. The rows (`rows`) carry what a person confirmed. */
export interface CpsaStatusOut {
  /** False: the document belongs to a service the establishment does not run (the first three answers are null: not applicable) */
  applies: boolean;
  /** Null: not applicable (a service not run here) */
  available: boolean | null;
  available_detail: string;
  /** Null: the PHC prints NA in 'Staff trained' for this document, or not applicable */
  trained: boolean | null;
  trained_detail: string;
  /** Null: the PHC prints NA in 'Implemented', or not applicable */
  implemented: boolean | null;
  implemented_detail: string;
  uploaded: boolean;
  last_upload: CpsaUploadOut | null;
}

/** A recorded upload to the HCE web portal. */
export interface CpsaUploadOut {
  upload_id: number;
  document_key: string;
  uploaded_on: string;
  portal_reference: string | null;
  note: string | null;
  recorded_by: number;
  recorded_by_name: string;
  recorded_at: string;
}

/** One row of the PHC's declaration (Annexure A), in the PHC's words. */
export interface DeclarationRowOut {
  /** The document's declaration row, from 1 (POST /phc/cpsa/declaration/answers row_no) */
  row_no: number;
  text: string;
  /** Available, Trained, Implemented */
  answers: DeclarationAnswerOut[];
  /** 'Document uploaded': an upload of the document is recorded */
  uploaded: boolean;
  /** Every answerable column confirmed by a person */
  confirmed: boolean;
}

/** One column of one declaration row. */
export interface DeclarationAnswerOut {
  question: "Available" | "Trained" | "Implemented";
  /** What the declaration prints: the person's answer, else the records' */
  value: "Yes" | "No" | "NotApplicable";
  /** The records' answer (evidence.py) */
  records: "Yes" | "No" | "NotApplicable";
  /** The PHC pre-prints NA in this column: it cannot be answered */
  fixed: boolean;
  /** Why the records answer so (what to fix or check) */
  reason: string;
  /** Null: nobody has confirmed it yet (printed with *) */
  confirmation: DeclarationConfirmationOut | null;
}

/** What a named person answered (the latest counts). */
export interface DeclarationConfirmationOut {
  answer: "Yes" | "No" | "NotApplicable";
  reason: string;
  /** Where the evidence is kept (required with a Yes) */
  evidence: string | null;
  decided_by_name: string;
  decided_at: string;
}

export interface MyPreferencesOut {
  theme: "Light" | "DarkHighContrast";
  language: "en" | "ur";
  ui_scale_pct: number;
  /** How a set of documents (the MSDS inspection pack) downloads: Separate = a button per document, one PDF each; Combined = one button, one PDF with all of them */
  pdf_download: "Separate" | "Combined";
  /** Anything else the frontend stores for this user */
  extra: Record<string, unknown>;
  /** Null until the user saves preferences for the first time */
  updated_at: string | null;
}

/** The hospital uploaded a document on the HCE web portal: record it (the upload itself happens on the Commission's site). */
export interface CpsaUploadIn {
  /** A key of GET /phc/cpsa */
  document_key: string;
  /** Default: today */
  uploaded_on?: string | null;
  /** The portal's acknowledgement or the file name uploaded */
  portal_reference?: string | null;
  note?: string | null;
}

/** The PHC's services list (Annexure B) with what the hospital declares. */
export interface ServicesDeclarationOut {
  declared: number;
  others: number;
  declared_at: string | null;
  declared_by_name: string | null;
  /** The filled Excel format the PHC accepts */
  xlsx_url: string;
  pdf_url: string;
  groups: ServicesGroupOut[];
}

export interface ServicesGroupOut {
  group_name: "MedicalAndAllied" | "SurgicalAndAllied" | "Laboratory" | "Imaging";
  label: string;
  /** Every service of the PHC's list in this group, declared or not, then the hospital's own lines */
  services: ServiceDeclarationOut[];
}

export interface ServiceDeclarationOut {
  service_name: string;
  group_name: "MedicalAndAllied" | "SurgicalAndAllied" | "Laboratory" | "Imaging";
  /** A name from the PHC's list; false: the hospital's own 'Others' line */
  is_listed: boolean;
  /** Marked Yes on the services list */
  declared: boolean;
  remarks: string | null;
  /** The row of the PHC's Excel format (null for an 'Others' line) */
  sheet_row: number | null;
}

/** The whole list the hospital declares (replaces the previous declaration). */
export interface ServicesDeclarationIn {
  items: ServiceDeclarationItemIn[];
}

export interface ServiceDeclarationItemIn {
  /** A service exactly as the PHC's list names it (GET /phc/services gives the names), or the hospital's own service for an 'Others' line (is_listed false) */
  service_name: string;
  /** True: a name from the PHC's list (its group is known); false: an 'Others' line */
  is_listed?: boolean;
  /** Required for an 'Others' line; ignored for a listed service */
  group_name?: "MedicalAndAllied" | "SurgicalAndAllied" | "Laboratory" | "Imaging" | null;
  /** The PHC's remarks column */
  remarks?: string | null;
}

/** A person's answer to one column of one row of the PHC's declaration (Annexure A), with the reason. */
export interface DeclarationAnswerIn {
  /** A key of GET /phc/cpsa */
  document_key: string;
  /** The document's declaration row (GET /phc/cpsa rows[].row_no) */
  row_no?: number;
  question: "Available" | "Trained" | "Implemented";
  /** Null: withdraw your answer (the records' answer counts again) */
  answer: "Yes" | "No" | "NotApplicable" | null;
  /** Why: what was checked, or why the records are wrong */
  reason: string;
  /** Where the evidence is kept: required with Yes (the drill report file, the signed SOP's place, the photo) */
  evidence?: string | null;
}

/** An answer a person gave, as recorded (the history keeps every one). */
export interface DeclarationAnswerRecordOut {
  answer_id: number;
  document_key: string;
  row_no: number;
  question: "Available" | "Trained" | "Implemented";
  /** Null: withdrawn (the records' answer counts) */
  answer: "Yes" | "No" | "NotApplicable" | null;
  reason: string;
  evidence: string | null;
  decided_by: number;
  decided_by_name: string;
  decided_at: string;
}

/** The PHC web portal's 20 Critical Patient Safety Areas and every document they require — GET /api/v1/phc/cpsa (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function overview(query?: { date_from?: string | null; date_to?: string | null }): Promise<CpsaOverviewOut> {
  return api<CpsaOverviewOut>("GET", withQuery(`/phc/cpsa`, query), undefined);
}

/** The PHC's 'Guidelines for CPSAs' (Word), as published — GET /api/v1/phc/cpsa/guidelines (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function guidelines(): Promise<unknown> {
  return api<unknown>("GET", `/phc/cpsa/guidelines`, undefined);
}

/** The PHC's own template or guideline for a document, as published — GET /api/v1/phc/cpsa/documents/{key}/template (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function template(key: string): Promise<unknown> {
  return api<unknown>("GET", `/phc/cpsa/documents/${key}/template`, undefined);
}

/** A CPSA document filled from the records (PDF) — GET /api/v1/phc/cpsa/documents/{key}/pdf (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function documentPdfPhcCpsaDocuments(key: string, query?: { date_from?: string | null; date_to?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/phc/cpsa/documents/${key}/pdf`, query), undefined);
}

/** A CPSA 1 list filled into the PHC's Excel format — GET /api/v1/phc/cpsa/documents/{key}/xlsx (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function documentXlsx(key: string): Promise<unknown> {
  return api<unknown>("GET", `/phc/cpsa/documents/${key}/xlsx`, undefined);
}

/** Every filled CPSA document as one PDF — GET /api/v1/phc/cpsa/pdf (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function combinedPdf(query?: { date_from?: string | null; date_to?: string | null }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/phc/cpsa/pdf`, query), undefined);
}

/** My preferences (theme, language, UI scale, PDF download) — GET /api/v1/settings/me (who may call: any logged-in user, for their own account (also before a forced password change where allowed)). */
export function getPrefs(): Promise<MyPreferencesOut> {
  return api<MyPreferencesOut>("GET", `/settings/me`, undefined);
}

/** Record that a document was uploaded on the HCE web portal — POST /api/v1/phc/cpsa/uploads (who may call: holders of msds.cpsa.manage). */
export function recordUpload(body: CpsaUploadIn): Promise<CpsaUploadOut> {
  return api<CpsaUploadOut>("POST", `/phc/cpsa/uploads`, body, { idempotent: true });
}

/** The record of uploads, newest first — GET /api/v1/phc/cpsa/uploads (who may call: holders of msds.view or msds.cpsa.manage). */
export function listUploads(query?: { document_key?: string | null; limit?: number }): Promise<CpsaUploadOut[]> {
  return api<CpsaUploadOut[]>("GET", withQuery(`/phc/cpsa/uploads`, query), undefined);
}

/** The PHC's services list with what the hospital declares — GET /api/v1/phc/services (who may call: holders of msds.view or msds.inspect or msds.cpsa.manage). */
export function declaredServices(): Promise<ServicesDeclarationOut> {
  return api<ServicesDeclarationOut>("GET", `/phc/services`, undefined);
}

/** Declare the services the hospital provides — PUT /api/v1/phc/services (who may call: holders of msds.cpsa.manage). */
export function declareServices(body: ServicesDeclarationIn): Promise<ServicesDeclarationOut> {
  return api<ServicesDeclarationOut>("PUT", `/phc/services`, body);
}

/** Confirm or correct one answer of the PHC declaration (Annexure A), with the reason — POST /api/v1/phc/cpsa/declaration/answers (who may call: holders of msds.cpsa.manage). */
export function recordAnswer(body: DeclarationAnswerIn): Promise<DeclarationRowOut> {
  return api<DeclarationRowOut>("POST", `/phc/cpsa/declaration/answers`, body, { idempotent: true });
}

/** The answers people gave on the declaration, newest first — GET /api/v1/phc/cpsa/declaration/answers (who may call: holders of msds.view or msds.cpsa.manage). */
export function listAnswers(query?: { document_key?: string | null; limit?: number }): Promise<DeclarationAnswerRecordOut[]> {
  return api<DeclarationAnswerRecordOut[]>("GET", withQuery(`/phc/cpsa/declaration/answers`, query), undefined);
}
